for(const nm of ["farmer1","unicorn","unicorn_foal_1","brownbear_1","brownbear","brownbear_cub_1","al_kharid_warrior","wizard","giantrat","goblin"]){
 const cands=npcs.filter(x=>x.cfg===nm||x.name==="Farmer"||x.name==="Unicorn"||x.name==="Bear");
 if(nm==="farmer1"||nm==="unicorn"||nm==="brownbear"){console.log("--",nm);for(const n of cands)console.log("  ",n.cfg,JSON.stringify({name:n.name,lv:n.vislevel,hp:n.hitpoints,atk:n.attack,str:n.strength,def:n.defence,mag:n.magic,rng:n.attackrange,op2:n.op2}));continue;}
 const n=npcs.find(x=>x.cfg===nm);
 console.log(nm, n?JSON.stringify({name:n.name,lv:n.vislevel,hp:n.hitpoints,atk:n.attack,str:n.strength,def:n.defence,mag:n.magic,rng:n.attackrange}):"NOT FOUND");
}
'

